function drawCameras(t){let el=$('#camera-feed');if(!el)return;let ctx=el.getContext('2d');if(activeMap.id==='polus'){const v=activeMap.cameras[cameraIndex];ctx.fillStyle='#000';ctx.fillRect(0,0,800,440);ctx.save();ctx.beginPath();ctx.rect(3,3,794,434);ctx.clip();ctx.translate(400,220);ctx.scale(.7,.7);ctx.translate(-v.x,-v.y);worldDraw(ctx,t,{camera:v});ctx.restore();ctx.fillStyle='#e83c45';ctx.beginPath();ctx.arc(760,25,7,0,Math.PI*2);ctx.fill();if($('#camera-view'))$('#camera-view').textContent=['EAST','CENTRAL','NORTHEAST','SOUTH','SOUTHWEST','NORTHWEST'][cameraIndex]+' · '+(cameraIndex+1)+' / 6';return;}let views=SKELD.cameras;ctx.fillStyle='#000';ctx.fillRect(0,0,800,440);for(let i=0;i<4;i++){let x=(i%2)*400,y=Math.floor(i/2)*220,v=views[i];ctx.save();ctx.beginPath();ctx.rect(x+3,y+3,394,214);ctx.clip();ctx.translate(x+200,y+110);ctx.scale(.43,.43);ctx.translate(-v.x,-v.y);worldDraw(ctx,t,{camera:v});ctx.restore();ctx.fillStyle='#000b';ctx.fillRect(x+4,y+4,390,24);ctx.font='11px monospace';ctx.fillStyle='#b7e8d8';ctx.fillText(v.name,x+13,y+20);ctx.fillStyle='#ee3444';ctx.beginPath();ctx.arc(x+376,y+16,4,0,6.28);ctx.fill();}}
const stars=Array.from({length:180},()=>({x:Math.random(),y:Math.random(),s:Math.random()*1.4+.4,speed:Math.random()*.012+.004}));
function drawSpace(t){const dpr=fitCanvas($('#space')),ctx=$('#space').getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#03050a';ctx.fillRect(0,0,innerWidth,innerHeight);for(const s of stars){let x=(s.x*innerWidth+t*s.speed)%innerWidth;ctx.globalAlpha=.3+.6*Math.abs(Math.sin(s.y*30+t*.0002));ctx.fillStyle='#d5e9ff';ctx.fillRect(x,s.y*innerHeight,s.s,s.s);}ctx.globalAlpha=1;}
